import { useState } from "react";
import "./Checker.css";

const VERDICT_CONFIG = {
  TRUE: { color: "#22c55e", bg: "#052e16", icon: "✅", label: "FACTUALLY TRUE" },
  FALSE: { color: "#ef4444", bg: "#2d0a0a", icon: "❌", label: "FACTUALLY FALSE" },
  "PARTIALLY TRUE": { color: "#f59e0b", bg: "#2d1a00", icon: "⚠️", label: "PARTIALLY TRUE" },
};

export default function Checker() {
  const [text, setText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleCheck = async () => {
    if (!text.trim()) return;
    setLoading(true);
    setError("");
    setResult(null);

    try {
      const res = await fetch("http://localhost:8000/api/check", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text }),
      });

      if (!res.ok) throw new Error("Server error");
      const data = await res.json();
      setResult(data);
    } catch (err) {
      setError("Something went wrong. Make sure backend is running!");
    } finally {
      setLoading(false);
    }
  };

  const handleClear = () => {
    setText("");
    setResult(null);
    setError("");
  };

  const config = result ? VERDICT_CONFIG[result.verdict] : null;

  return (
    <div className="checker">
      <div className="checker-intro">
        <h2>Detect AI Hallucinations Instantly</h2>
        <p>Paste any AI-generated text below and we'll fact-check it using LLaMA 3</p>
      </div>

      <div className="input-section">
        <textarea
          className="text-input"
          placeholder="Paste AI-generated text here... e.g. 'The Eiffel Tower is located in Berlin and was built in 1920.'"
          value={text}
          onChange={(e) => setText(e.target.value)}
          rows={6}
        />
        <div className="input-meta">
          <span className="char-count">{text.length} characters</span>
          <div className="btn-group">
            {text && (
              <button className="btn-clear" onClick={handleClear}>
                Clear
              </button>
            )}
            <button
              className="btn-check"
              onClick={handleCheck}
              disabled={!text.trim() || loading}
            >
              {loading ? (
                <span className="loading-dots">
                  <span>Analyzing</span>
                  <span className="dots">...</span>
                </span>
              ) : (
                "🔍 Check Now"
              )}
            </button>
          </div>
        </div>
      </div>

      {error && <div className="error-box">{error}</div>}

      {result && config && (
        <div className="result-card" style={{ borderColor: config.color }}>
          {/* Verdict Header */}
          <div className="verdict-header" style={{ background: config.bg }}>
            <span className="verdict-icon">{config.icon}</span>
            <div>
              <div className="verdict-label" style={{ color: config.color }}>
                {config.label}
              </div>
              <div className="confidence-row">
                <span>Confidence:</span>
                <div className="confidence-bar">
                  <div
                    className="confidence-fill"
                    style={{
                      width: `${result.confidence}%`,
                      background: config.color,
                    }}
                  />
                </div>
                <span style={{ color: config.color }}>{result.confidence}%</span>
              </div>
            </div>
          </div>

          {/* Explanation */}
          <div className="result-section">
            <h4>📋 Explanation</h4>
            <p>{result.explanation}</p>
          </div>

          {/* Key Claims */}
          {result.key_claims?.length > 0 && (
            <div className="result-section">
              <h4>🔑 Key Claims Analyzed</h4>
              <ul className="claims-list">
                {result.key_claims.map((claim, i) => (
                  <li key={i}>{claim}</li>
                ))}
              </ul>
            </div>
          )}

          {/* Corrections */}
          {result.corrections && result.corrections !== "No corrections needed." && (
            <div className="result-section corrections">
              <h4>✏️ Corrections</h4>
              <p>{result.corrections}</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
